package net.civeira.phylax.feature.notification.message.domain.valueholder;

import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.message.domain.Message;
import net.civeira.phylax.feature.notification.message.domain.valueobject.LockAtVO;

class LockAtValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of lock at of message")
  void test_lock_at_value_holder_assign_plain_value() {
    Object holder = new Object();
    LockAtValueHolder<Object> value = new LockAtValueHolder<>(holder);
    Assertions.assertSame(holder, value.lockAt(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "Setters must return the holder");
    Assertions.assertTrue(value.getLockAtValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        value.getLockAt().orElse(null), "The plain value must be recovered");
    Assertions.assertSame(holder, value.lockAtNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLockAtValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getLockAt().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of lock at of message")
  void test_lock_at_value_holder_assign_value_object() {
    Object holder = new Object();
    LockAtValueHolder<Object> value = new LockAtValueHolder<>(holder);
    LockAtVO vo = LockAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertFalse(value.getLockAtValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.lockAt(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLockAtValue().orElseThrow());
    Assertions.assertSame(holder, value.lockAt(Optional.empty()));
    Assertions.assertFalse(value.getLockAtValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.lockAt(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLockAtValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of lock at of message against the original")
  void test_lock_at_value_holder_read() {
    Object holder = new Object();
    LockAtValueHolder<Object> value = new LockAtValueHolder<>(holder);
    LockAtVO vo = LockAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    LockAtVO other = LockAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Message original = Mockito.mock(Message.class);
    Mockito.when(original.getLockAtValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLockAt(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLockAt(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.lockAt(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLockAt(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLockAt(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of lock at of message")
  void test_lock_at_value_holder_unset() {
    Object holder = new Object();
    LockAtValueHolder<Object> value = new LockAtValueHolder<>(holder);
    LockAtVO vo = LockAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    value.lockAt(vo);
    Assertions.assertSame(holder, value.unsetLockAtIfMatches("lockAt_other"));
    Assertions.assertTrue(value.getLockAtValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLockAtIfMatches("lockAt"));
    Assertions.assertFalse(value.getLockAtValue().isPresent(),
        "The field name must clear the value");
    value.lockAt(vo);
    Assertions.assertSame(holder, value.unsetLockAt());
    Assertions.assertFalse(value.getLockAtValue().isPresent(), "Unset must clear the value");
  }
}
